import{_ as t,o as a,c as o,ag as d}from"./chunks/framework.BZohXCq9.js";const f=JSON.parse('{"title":"Student Dashboard -> Payment History (deep)","description":"","frontmatter":{},"headers":[],"relativePath":"modules/student-dashboard/payment-history.md","filePath":"modules/student-dashboard/payment-history.md"}'),r={name:"modules/student-dashboard/payment-history.md"};function s(n,e,i,l,c,u){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="student-dashboard-payment-history-deep" tabindex="-1">Student Dashboard -&gt; Payment History (deep) <a class="header-anchor" href="#student-dashboard-payment-history-deep" aria-label="Permalink to &quot;Student Dashboard -&gt; Payment History (deep)&quot;">​</a></h1><p><strong>Module:</strong> <code>student-dashboard</code><br><strong>Feature:</strong> <code>payment-history</code><br><strong>Route:</strong> <code>/student-dashboard/payment-history</code></p><p>This screen is the student-facing financial ledger. It shows lesson payments, refunds, rejected/cancelled financial outcomes, summary cards, and detailed transaction rows with pagination.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><ul><li>Give students a clear view of what they paid and what was refunded.</li><li>Separate completed vs refund vs rejected transaction states.</li><li>Show lesson-slot context for each transaction row.</li><li>Provide a modal detail surface for transaction metadata.</li></ul><h2 id="frontend-files" tabindex="-1">Frontend files <a class="header-anchor" href="#frontend-files" aria-label="Permalink to &quot;Frontend files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th><th>Integration</th></tr></thead><tbody><tr><td><code>Frontend/src/pages/private/student-dashboard/StudentPaymentHistoryPage.tsx</code></td><td>Main payment-history page</td><td>Calls student transaction list/count/stats queries; renders stat cards, filter tabs, paginated table, and detail modal.</td></tr><tr><td><code>Frontend/src/graphql/Queries/transactionQueries.ts</code></td><td>Transaction GraphQL definitions</td><td>Defines student transaction list/count/stats queries and related fields like <code>lessonSummary</code>.</td></tr></tbody></table><h2 id="frontend-graphql" tabindex="-1">Frontend GraphQL <a class="header-anchor" href="#frontend-graphql" aria-label="Permalink to &quot;Frontend GraphQL&quot;">​</a></h2><h3 id="get-student-transactions" tabindex="-1"><code>GET_STUDENT_TRANSACTIONS</code> <a class="header-anchor" href="#get-student-transactions" aria-label="Permalink to &quot;`GET_STUDENT_TRANSACTIONS`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/Queries/transactionQueries.ts</code></li><li>Query field: <code>getStudentTransactions(limit, offset, view)</code></li><li>Used by: main transaction table.</li></ul><h3 id="get-student-transactions-count" tabindex="-1"><code>GET_STUDENT_TRANSACTIONS_COUNT</code> <a class="header-anchor" href="#get-student-transactions-count" aria-label="Permalink to &quot;`GET_STUDENT_TRANSACTIONS_COUNT`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/Queries/transactionQueries.ts</code></li><li>Query field: <code>getStudentTransactionCount(view)</code></li><li>Used by: pagination.</li></ul><h3 id="get-student-transaction-stats" tabindex="-1"><code>GET_STUDENT_TRANSACTION_STATS</code> <a class="header-anchor" href="#get-student-transaction-stats" aria-label="Permalink to &quot;`GET_STUDENT_TRANSACTION_STATS`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/Queries/transactionQueries.ts</code></li><li>Query field: <code>getStudentTransactionStats</code></li><li>Used by: top summary cards (<code>totalSpent</code>, <code>totalRefunded</code>, counts).</li></ul><h3 id="refund-request-history" tabindex="-1">Refund request history <a class="header-anchor" href="#refund-request-history" aria-label="Permalink to &quot;Refund request history&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/mutations/refundRequest.ts</code></li><li>Query field: <code>GET_MY_REFUND_REQUESTS</code></li><li>Used when the UI needs refund-request state beyond the raw transaction ledger.</li></ul><h2 id="backend-schema" tabindex="-1">Backend schema <a class="header-anchor" href="#backend-schema" aria-label="Permalink to &quot;Backend schema&quot;">​</a></h2><h3 id="typedefs" tabindex="-1">TypeDefs <a class="header-anchor" href="#typedefs" aria-label="Permalink to &quot;TypeDefs&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/typeDefs/transaction.typeDefs.js</code></li><li>Relevant query fields: <ul><li><code>getStudentTransactions(limit, offset, view)</code></li><li><code>getStudentTransactionCount(view)</code></li><li><code>getStudentTransactionStats</code></li><li><code>getStudentBookingTransactions(bookingId)</code></li></ul></li><li>Relevant types: <ul><li><code>Transaction</code></li><li><code>StudentTransactionStats</code></li></ul></li><li>File: <code>server/src/graphql/typeDefs/refundRequest.typeDefs.js</code><ul><li><code>getMyRefundRequests</code></li></ul></li></ul><h3 id="resolvers" tabindex="-1">Resolvers <a class="header-anchor" href="#resolvers" aria-label="Permalink to &quot;Resolvers&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/resolvers/transaction.resolver.js</code><ul><li><code>Query.getStudentTransactions</code></li><li><code>Query.getStudentTransactionCount</code></li><li><code>Query.getStudentTransactionStats</code></li><li><code>Transaction.lessonSummary</code></li></ul></li><li>File: <code>server/src/graphql/resolvers/refundRequest.resolver.js</code><ul><li><code>Query.getMyRefundRequests</code></li></ul></li></ul><h2 id="main-backend-dependencies" tabindex="-1">Main backend dependencies <a class="header-anchor" href="#main-backend-dependencies" aria-label="Permalink to &quot;Main backend dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>server/src/models/transaction.model.js</code></td><td>Primary financial transaction store</td></tr><tr><td><code>server/src/models/refundRequest.model.js</code></td><td>Student refund-request state</td></tr><tr><td><code>server/src/models/studentBooking.model.js</code></td><td>Source for lesson summary / slot context</td></tr><tr><td><code>server/src/services/transactionService.js</code></td><td>Creates many of the ledger rows displayed here</td></tr><tr><td><code>server/src/services/stripeService.js</code></td><td>Payment/refund helpers behind transaction creation</td></tr></tbody></table><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><ol><li>Student opens <code>/student-dashboard/payment-history</code>.</li><li>The page loads: <ul><li>transaction list</li><li>transaction count</li><li>stats summary</li></ul></li><li>Filter tabs change the <code>view</code> variable (<code>all</code>, <code>completed</code>, <code>refund</code>, <code>rejected</code>).</li><li>Pagination updates the <code>offset</code>.</li><li>Backend returns only the current student’s ledger rows and aggregate totals.</li><li><code>lessonSummary</code> is resolved from booking/slot data so the table can show which lesson each transaction belongs to.</li></ol><h2 id="developer-notes" tabindex="-1">Developer notes <a class="header-anchor" href="#developer-notes" aria-label="Permalink to &quot;Developer notes&quot;">​</a></h2><ul><li>This page is transaction-ledger driven, not booking-ledger driven; one booking can produce multiple financial rows.</li><li>Refund requests and refund transactions are related but not identical concepts. The student may see both the request state and the final refund transaction depending on the UI surface.</li><li>Server-side pagination is already implemented, so large student ledgers do not require fetching every row at once.</li></ul>',27)])])}const p=t(r,[["render",s]]);export{f as __pageData,p as default};
